{
  "claims": [
    {
      "claim": "Direct PET and tissue measurements of rifampicin (the query molecule) after systemic administration demonstrate brain concentrations that exceed the therapeutic MIC: baboon brain ~0.9–1.2 µg/ml and ~3–4× MIC, human resected brain tissue 0.29 µg/ml, and mouse brain 10.25 µg/ml. This is strong transferable evidence of meaningful CNS access despite modest CSF ratios.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-2",
        "Record 12-3",
        "Record 12-5",
        "Record 12-6"
      ]
    },
    {
      "claim": "In a rabbit TBM model, the closely related rifamycin rifabutin achieved a median brain/plasma ratio of 0.856 and CSF/plasma ratio of 0.227, and in humans CSF concentrations averaged about 50% of serum concentrations. This indicates that rifamycin-class drugs can achieve meaningful CNS exposure in the setting of meningeal inflammation.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-2",
        "Record 13-9"
      ]
    },
    {
      "claim": "Rifapentine, a very close rifamycin analog, showed poor CSF penetration in human tuberculous meningitis (CSF <0.15 mg/L vs serum 7.2 mg/L) and <20% brain/plasma in rats. This is contradictory class-level evidence, but rifapentine is more lipophilic and more highly protein-bound than the query rifampicin, and direct rifampicin brain-tissue data outweigh this analog.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 11-4"
      ]
    },
    {
      "claim": "Healthy-baboon PET classified rifampicin/metabolites as poorly penetrating the intact BBB, and rifabutin is an ABCB1 substrate with an efflux ratio of 4.7. These are contradictory signals indicating restricted passive CNS penetration, but they are not decisive for tuberculous meningitis, where inflammation increases blood-brain barrier permeability and measured rifampicin brain concentrations still exceed therapeutic MICs.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 12",
        "Molecule 13"
      ],
      "record_ids": [
        "Record 12-1",
        "Record 13-10"
      ]
    },
    {
      "claim": "Several distant scaffolds with poor CNS results (mithramycin, levofloxacin, temsirolimus, brusatol, trabectedin, novobiocin, rapamycin) have low structural similarity to rifampicin and are not mechanistically transferable; these records are given little weight compared with direct rifamycin-class CNS measurements.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 1",
        "Molecule 4",
        "Molecule 6",
        "Molecule 8",
        "Molecule 15",
        "Molecule 17",
        "Molecule 20"
      ],
      "record_ids": [
        "Record 1-1",
        "Record 4-1",
        "Record 6-1",
        "Record 8-1",
        "Record 15-1",
        "Record 17-1",
        "Record 20-1"
      ]
    }
  ],
  "final_prediction": "pass"
}

